[2] = { ["id"] = 2, ["name"] = "Sharptalon's Claw", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 2 }, ["description"] = "The mighty hippogryph Sharptalon has been slain, with the claw of the felled beast serving as a testament to your victory. Senani Thunderheart at the Silverwind Refuge will no doubt be interested in seeing this trophy as proof of your deeds.", ["objectivesText"] = "Bring Sharptalon's Claw to Senani Thunderheart at Silverwind Refuge. Progress: What have you there, <class>? Could it be....?", ["rewardGold"] = 99850, ["rewardXP"] = 1010, ["rewardItems"] = { 16305 }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12696, ["x"] = 0.498, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["startItems"] = { 16305 } },
[11] = { ["id"] = 11, ["name"] = "Riverpaw Gnoll Bounty", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 11, 35, 37, 40, 45, 46, 47, 52, 59, 60, 62, 71, 76, 83, 84, 85, 86, 87, 88, 106, 107, 111, 112, 114, 123, 147, 176, 5545, 26152, 37112 }, ["series"] = { 239 }, ["description"] = "Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest . A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder. Another group has infested the areas near Stone Cairn Lake to the east. The Stormwind Army will commend whomever helps kill them. Bring me their painted gnoll armbands as proof of your deed.", ["objectivesText"] = "Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks. Progress: Hail, <name>. Have you been killing Gnolls...?", ["rewardXP"] = 200, ["rewardItems"] = { 782, 2238, 57526, 57527, 131192 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 963, ["x"] = 0.242, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 963, ["x"] = 0.242, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 37, ["questLines"] = { { ["id"] = 566, ["name"] = "Elwynn Forest", ["orderIndex"] = 28, ["flags"] = 0 } } },
[23] = { ["id"] = 23, ["name"] = "Ursangous' Paw", ["level"] = 24, ["requiredLevel"] = 19, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 331, ["storyline"] = { 23 }, ["description"] = "The mighty bear Ursangous is no more! The small quarter-crescent emblem on its paw indicates that this beast was trained by the night elves to prowl the forest in search of their enemies. There is no telling how many of your Horde allies fell to this creature. The paw should be brought to Tarkan at Silverwind Refuge. He will be pleased that such a weapon has been removed from the enemy's arsenal.", ["objectivesText"] = "Bring Ursangous' Paw to Captain Tarkan at Silverwind Refuge. Progress: Ah - <name> - I was just thinking about you! How goes your hunting?", ["rewardGold"] = 1700, ["rewardXP"] = 1950, ["rewardItems"] = { 16303 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 331 } }, ["questType"] = "standard", ["startItems"] = { 16303 } },
[24] = { ["id"] = 24, ["name"] = "Shadumbra's Head", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 24 }, ["description"] = "The once swift Shadumbra now lies still as you claim victory over it. This legenday creature is dear to the night elves. Its head should serve as an intimidating trophy, and as a sign of the end of the Alliance in Ashenvale . Captain Goggath at Hellscream's Watch will no doubt be delighted to receive the head of the slain nightsaber.", ["objectivesText"] = "Bring Shadumbra's Head to Captain Goggath at Hellscream's Watch. Progress: Yes, <class>?", ["rewardGold"] = 105000, ["rewardXP"] = 1010, ["rewardItems"] = { 16304 }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12696, ["x"] = 0.498, ["y"] = 0.652 }, { ["mapID"] = 63, ["npcID"] = 34359, ["x"] = 0.3855, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["startItems"] = { 16304 } },
[25] = { ["id"] = 25, ["name"] = "Simmer Down Now", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 25 }, ["description"] = "You should've seen it, <class>! The elves thought Silverwind to be impenetrable. With its heavy defenses and their army of water elementals, they were almost right. Almost. One of our mages was able to summon a twisted elemental designed to send the others into a chaotic rage. Ahh, the looks on their faces! <Tarkan laughs.> Unfortunately, the mage who summoned it fell in battle. Now I need someone to bring down our creation.", ["objectivesText"] = "Captain Tarkan at Silverwind Refuge wants you to defeat Tideress and 12 Befouled Water Elementals at Mystral Lake.", ["rewardGold"] = 105000, ["rewardXP"] = 1010, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 34559, ["x"] = 0.5, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12737, ["x"] = 0.74, ["y"] = 0.606 }, { ["mapID"] = 63, ["npcID"] = 34559, ["x"] = 0.5, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[184] = { ["id"] = 184, ["name"] = "Furlbrow's Deed", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 12, ["mapID"] = 52, ["storyline"] = { 184 }, ["description"] = "This is an old deed to an expanse of farmlands within Westfall . It is signed by a Theodore Furlbrow and cosigned by his wife, Verna. And on the back of the deed are hastily scrawled words: \"We leaned on Furlbrow and got his deed. Thought it might be handy if you wanted to forge one of these for your own place. The Furlbrows won't give us trouble. Last I saw them they were on their way out of Westfall , stuck with a broken wagon.\" You think the Furlbrows might want their deed back...", ["objectivesText"] = "Bring Furlbrow's Deed to the Jansen Stead in Westfall . Progress: We don't need any civilian vigilante types getting involved, kid. Leave this one to the professionals.", ["rewardXP"] = 555, ["rewardItems"] = { 1971, 1972, 86570 }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 42308, ["x"] = 0.485, ["y"] = 0.4215 }, { ["mapID"] = 52, ["npcID"] = 42309, ["x"] = 0.581, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.4215 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["startItems"] = { 1972 } },
[185] = { ["id"] = 185, ["name"] = "Tiger Hunting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 186, 187, 188 }, ["description"] = "When I was but a young girl, my father trained me in the art of tiger hunting. You'll find the young felines much easier to track and slay. One can often find young tigers near the expedition camp. Test your tracking skills and see if you can hunt some of the beasts down. Start your hunt near our camp, to the south.", ["objectivesText"] = "Hunt 10 Young Stranglethorn Tigers .", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 717, ["x"] = 0.444, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 717, ["x"] = 0.444, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 44, ["flags"] = 0 } } },
