[188] = { ["id"] = 188, ["name"] = "Tiger Mastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 185, 186, 187 }, ["description"] = "Legends speak of an elusive tigress... a feline so powerful that she dwarfs even the elder males. The hunters at Nesingwary's Expedition have hunted for her without success. Many of them have fallen prey to her raking claws, their bodies now decaying at the foot of her hill, north of Grom'gol. They call the beast Sin'Dall. You resolve to do what no <race> has done before: hunt, kill, and claim the paw of Sin'Dall .", ["objectivesText"] = "Hunt Sin'Dall and return with her paw. Progress: How goes the hunt?", ["rewardGold"] = 315000, ["rewardXP"] = 1770, ["rewardItems"] = { 3879, 61113, 61114, 61115, 61116, 131200 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 717, ["x"] = 0.444, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 717, ["x"] = 0.444, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 56, ["flags"] = 0 } } },
[190] = { ["id"] = 190, ["name"] = "Panther Hunting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 191, 192, 193 }, ["description"] = "If you want to be a part of the hunt with this crack group under Hemet Jr.'s leadership, you're going to need to prove yourself an able panther hunter. You should start out easy: just focus on the young panthers for now. As you improve and gain experience as a hunter, you will undoubtedly find increasingly dangerous quarry. Start by heading east. Return to me when you are a master panther hunter.", ["objectivesText"] = "Hunt 10 Young Panthers .", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 718, ["x"] = 0.438, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 718, ["x"] = 0.438, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 45, ["flags"] = 0 } } },
