[192] = { ["id"] = 192, ["name"] = "Panther Prowess", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 190, 191, 193 }, ["description"] = "Now the hard part. As panthers grow older, they become more wily, blending in with their environment and becoming difficult to spot. These cunning panthers are known by the name \"shadowmaw\", for their tendency to suddenly appear out of the darkness... with a waiting mouth full of teeth. If you want to prove yourself as a true panther hunter, shadowmaws are the only way to do so. They prowl to the southeast, across the river.", ["objectivesText"] = "Hunt 5 Shadowmaw Panthers .", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 718, ["x"] = 0.438, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 718, ["x"] = 0.438, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 53, ["flags"] = 0 } } },
[193] = { ["id"] = 193, ["name"] = "Panther Mastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 190, 191, 192 }, ["description"] = "You've almost proven yourself to be a master hunter of panthers. Yet there is one panther which has eluded your grasp. Songs are sung about a mighty panther by the name of Bhag'thera. You will see if you can use your skills to kill the great beast. Bringing the Fang of Bhag'thera to Erlgadin should be proof enough that you are a master panther hunter.", ["objectivesText"] = "Obtain the Fang of Bhag'thera . Progress: You're still alive! Excellent! How fares the hunt?", ["rewardGold"] = 315000, ["rewardXP"] = 1770, ["rewardItems"] = { 3876, 61107, 61108, 61109 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 718, ["x"] = 0.438, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 718, ["x"] = 0.438, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 57, ["flags"] = 0 } } },
[194] = { ["id"] = 194, ["name"] = "Raptor Hunting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 195, 196, 197 }, ["description"] = "So you think your hunting skills are in tip-top shape? I can put them to the test in a jiffy. Head out into that jungle and kill ten Stranglethorn raptors . We'll see just how much of a big game hunter you are. And no, I won't tell you where you can find them! Locating the beasts is half the challenge. Okay, go west.", ["objectivesText"] = "Hunt 10 Stranglethorn Raptors .", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 46, ["flags"] = 0 } } },
[195] = { ["id"] = 195, ["name"] = "Raptor Stalking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 194, 196, 197 }, ["description"] = "It is time to step up the challenge. Venturing into the jungle and bagging 10 lashtail raptors should be sufficient. They will certainly be stronger than the raptors you have already disposed of. The lashtail raptors mainly stay southeast of here, near the Kal'ai Ruins.", ["objectivesText"] = "Hunt 10 Lashtail Raptors .", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 50, ["flags"] = 0 } } },
[196] = { ["id"] = 196, ["name"] = "Raptor Prowess", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 194, 195, 197 }, ["description"] = "A particularly cagey brand of raptor, known by locals as the \" Jungle Stalker \", prowls the forests to the south, across the river. They are far more difficult to track down and kill than the other breeds you've been trying your luck at. Killing these Jungle Stalkers will undoubtedly make for a good tale around the fire.", ["objectivesText"] = "Hunt 10 Jungle Stalkers .", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 54, ["flags"] = 0 } } },
[197] = { ["id"] = 197, ["name"] = "Raptor Mastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 194, 195, 196 }, ["description"] = "Before returning to Nesingwary's Expedition, you will have to complete the impossible: hunt the raptor that no other hunter has been able to capture. That beast goes by the name of Tethis, and he's been known to terrorize the southeastern corner of Northern Stranglethorn . Bringing Tethis' talon back to that dwarf hunter should be proof that you are no ordinary <race>.", ["objectivesText"] = "Hunt Tethis. Progress: Ah, so you're hunting Tethis? Tracked her all the way back to camp, did you?", ["rewardGold"] = 315000, ["rewardXP"] = 1770, ["rewardItems"] = { 3877, 61110, 61111, 61112, 131201 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 58, ["flags"] = 0 } } },
[208] = { ["id"] = 208, ["name"] = "Big Game Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["description"] = "<name>, you are a hunter worthy of our company. From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated. You have killed the ferocious Sin'Dall, the elusive Bhag'thera, and the treacherous Tethis. But the true prize is the head of King Bangalash. That white tiger is the reason I am here... yet still, he taunts me from his roost to the south. Kill King Bangalash and your hunting prowess is proven to be second to none.", ["objectivesText"] = "Hunt for the head of King Bangalash, the great white tiger. Progress: I see you're back, old bloke. King Bangalash has caused me to come crawling back to camp many times. Hang in there.", ["rewardGold"] = 175950, ["rewardXP"] = 2125, ["rewardItems"] = { 3880, 17687, 61124, 61125, 61126, 61127, 131202 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 59, ["flags"] = 0 } } },
[216] = { ["id"] = 216, ["name"] = "Between a Rock and a Thistlefur", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 216 }, ["description"] = "The Thistlefur furbolgs are threatening our expansion! Thistlefur Village to our west blocks the way between us here and the Splintertree Post. It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path. <name>, we must not allow... an expansion path gap! Proceed to Thistlefur Village and thin out the furbolgs. You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!", ["objectivesText"] = "Karang Amakkar at Hellscream's Watch wants you to take down any 15 Thistlefur furbolg in Thistlefur Village.", ["rewardGold"] = 280900, ["rewardXP"] = 1010, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 12757, ["x"] = 0.378, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12757, ["x"] = 0.378, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[309] = { ["id"] = 309, ["name"] = "Protecting the Shipment", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 38, ["mapID"] = 48, ["storyline"] = { 309 }, ["series"] = { 13639, 13650 }, ["description"] = "We need to get this powder to Ironband, but this cart isn't going anywhere now. It'll be a lot for us to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for us now that Saean is with them. I'll feel a lot better if you helped me watch over things. Miran can offload the powder kegs at camp while you and I protect the cart.", ["objectivesText"] = "Protect Huldar and the Ironband Caravan, and then inform Prospector Ironband . Progress: I'm glad to finally have my powder! We're on top of some amazing discoveries.", ["rewardGold"] = 105000, ["rewardXP"] = 925, ["rewardItems"] = { 58981, 58982, 58983, 131204 }, ["starts"] = { { ["mapID"] = 48, ["npcID"] = 2057, ["x"] = 0.564, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 48, ["npcID"] = 1344, ["x"] = 0.652, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 48, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 48 }, ["zone"] = { 38 } }, ["questType"] = "standard" },
[583] = { ["id"] = 583, ["name"] = "Welcome to the Jungle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 33, ["mapID"] = 50, ["storyline"] = { 185, 186, 187, 188, 190, 191, 192, 193, 194, 195, 196, 197, 208, 583, 26269, 26278, 26280, 26298, 26299, 26300, 26301, 26302, 26303, 26305, 26317, 26321, 26323, 26325, 26330, 26332, 26334, 26338, 26343, 26344, 26345, 26350, 26351, 26359, 26360, 26362, 26386, 26729, 26730, 26731, 26735, 26736, 26737, 26738, 26739, 26742, 26743, 26745, 26746, 26747, 26748, 26749, 26772, 26773, 26774, 26775 }, ["series"] = { 26340 }, ["description"] = "Welcome to Stranglethorn! Perhaps you're not aware of this, but that dwarf over there is the son of the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter. Like his father, he's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, <class>. Go and speak with him. He's a chip off the old block, so perhaps he can give you some hunting pointers.", ["objectivesText"] = "Speak with Hemet Nesingwary Jr.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 52019 }, ["starts"] = { { ["mapID"] = 50, ["npcID"] = 716, ["x"] = 0.442, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 50, ["npcID"] = 715, ["x"] = 0.44, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 50, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 50 }, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 414, ["name"] = "Northern Stranglethorn", ["orderIndex"] = 42, ["flags"] = 0 } } },
[840] = { ["id"] = 840, ["name"] = "Conscript of the Horde", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 840 }, ["series"] = { 871, 872, 26642, 28494 }, ["description"] = "Hmm, you look pretty strong. Listen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance. Take this recruitment letter to Kargal and see if he'll sign it.", ["objectivesText"] = "Give Kargal Battlescar at the Barrens outpost your recruitment letter . Progress: What do you want, pup? If you're not here for recruitment, I don't have time for you.", ["rewardXP"] = 370, ["rewardItems"] = { 4992 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 3336, ["x"] = 0.508, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3337, ["x"] = 0.676, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1, 10 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[844] = { ["id"] = 844, ["name"] = "Plainstrider Menace", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 844 }, ["description"] = "Are you familiar with plainstriders? Useless animals. Can't fly. Gamey. Brain the size of my knuckle. Too dim to get out of the way of a moving cart. I've broken more axles thanks to their thick skulls... Sometimes I think the quilboar intentionally frighten flocks of them into the path of our caravans just prior to an ambush. Make me proud, <class>. Cut a swath through those filthy birds to keep the roads free, and bring me their beaks as proof.", ["objectivesText"] = "Collect 7 Plainstrider Beaks . Progress: Have you collected the plainstrider beaks ?", ["rewardGold"] = 105000, ["rewardXP"] = 740, ["rewardItems"] = { 5087 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 }, { ["mapID"] = 10, ["npcID"] = 34258, ["x"] = 0.558, ["y"] = 0.398667 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 }, { ["mapID"] = 10, ["npcID"] = 34258, ["x"] = 0.558, ["y"] = 0.398667 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[845] = { ["id"] = 845, ["name"] = "The Zhevra", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["description"] = "If you wish to serve my beloved horde, you'll have to prove your strength to me, pup. You can cut your teeth by hunting zhevra. They may not be the strongest of beasts in the Barrens, but stay clear of their kick or you'll regret it. Hunt the zhevra to the north and south, and collect their hooves. Bring them to me and perhaps we'll next send you against something tougher.", ["objectivesText"] = "Slay Zhevra Runners to collect 4 Zhevra Hooves . Progress: How many zhevra have you slain?", ["rewardGold"] = 309800, ["rewardXP"] = 740, ["rewardItems"] = { 5086 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 22, ["flags"] = 0 } } },
[848] = { ["id"] = 848, ["name"] = "Fungal Spores", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 13998, 13999 }, ["description"] = "The oases of the Barrens hide a mystery. Life energy flows from their waters, invigorating the plants and beasts that drink it. Invigorating, and altering. There is a mushroom that grows near the Forgotten Pools to the northwest. Its spores hold properties that we, the apothecaries of Lordaeron, find useful. Bring me these spores and you will earn our gratitude.", ["objectivesText"] = "Collect 5 Fungal Spores from mushrooms at the Forgotten Pools. Progress: Do you have the spores, <name>? My associates and I are eager to study this phenomenon...", ["rewardGold"] = 210000, ["rewardXP"] = 740, ["rewardItems"] = { 5012 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3390, ["x"] = 0.486, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3390, ["x"] = 0.486, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 12, ["flags"] = 0 } } },
[851] = { ["id"] = 851, ["name"] = "Verog the Dervish", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 14072 }, ["description"] = "Verog may be hard to find, but judging by the info you gathered, his mate Wyneth is always in his command tent just west of here. If we kill her, Verog will come running. Regthar sent us here to scout, but he also said we should seize any opportunity to upset the centaur chain of command if we can. Lure out Verog and kill him!", ["objectivesText"] = "Kill Wyneth in order to lure out Verog the Dervish, then slay him and grab his head. Progress: Did you find Verog, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 555, ["rewardItems"] = { 5023, 59566, 59567, 131219 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552 }, { ["mapID"] = 10, ["npcID"] = 34638, ["x"] = 0.552, ["y"] = 0.784 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552 }, { ["mapID"] = 10, ["npcID"] = 34638, ["x"] = 0.552, ["y"] = 0.784 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 19, ["flags"] = 0 } } },
[852] = { ["id"] = 852, ["name"] = "Hezrul Bloodmark", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 14073 }, ["description"] = "Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us. So kill him. Bring me Hezrul's Head , and I will mount it from this outpost, so that they may know fear. Hezrul leads his people from the Lushwater Oasis, to the south.", ["objectivesText"] = "Slay Hezrul Bloodmark and collect his head. Progress: Is Hezrul defeated, <name>?", ["rewardGold"] = 341600, ["rewardXP"] = 740, ["rewardItems"] = { 5025, 59585, 59586, 59587, 131220 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 20, ["flags"] = 0 } } },
[855] = { ["id"] = 855, ["name"] = "Centaur Bracers", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 855 }, ["description"] = "The centaur leadership relies on a core of trusted, disciplined warriors to keep the others in line. If we reduce their numbers, the Kolkar will have no might with which to support their rage. And so, I have a bounty task for you. Around the Lushwater Oasis to the south, slay Kolkar Marauders and Stormseers to collect their bracers. Return when you have a heap of these trophies and the Horde will reward you well.", ["objectivesText"] = "Collect 10 Centaur Bracers from Kolkar Marauders and Stormseers. Progress: How goes your hunting, <name>?", ["rewardXP"] = 740, ["rewardItems"] = { 5030, 59583, 59584, 131221 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[858] = { ["id"] = 858, ["name"] = "Ignition", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 858 }, ["series"] = { 863 }, ["description"] = "I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem. We need to get out of here on the double! Search the upper level of the derrick, Supervisor Lugwizzle should have a key for this shredder. Help me out here!", ["objectivesText"] = "Get the Ignition Key from Supervisor Lugwizzle. Progress: Quick, we need to get out of here before someone gets suspicious!", ["rewardGold"] = 341600, ["rewardXP"] = 740, ["rewardItems"] = { 5050 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3439, ["x"] = 0.56125, ["y"] = 0.1895 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3439, ["x"] = 0.56125, ["y"] = 0.1895 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.56125, ["y"] = 0.1895 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[863] = { ["id"] = 863, ["name"] = "The Escape", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 863 }, ["series"] = { 858 }, ["description"] = "I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?", ["objectivesText"] = "Protect Wizzlecrank and the stolen goblin shredder on the way out of the Sludge Fens.", ["rewardGold"] = 210000, ["rewardXP"] = 925, ["rewardItems"] = { 59577, 59578, 59579, 131222, 155388, 155389, 155390, 155391, 155409, 155410, 155411, 155412 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3439, ["x"] = 0.56125, ["y"] = 0.1895 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3442, ["x"] = 0.622, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.56125, ["y"] = 0.1895 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[865] = { ["id"] = 865, ["name"] = "It's Gotta be the Horn", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 865 }, ["description"] = "The raptors of the Barrens are smarter than raptors in other lands. I think all those smarts are hiding in their horns! If so, then I could grind their horns into powder and use it to make \"smart drinks.\" I'll make a fortune! Here's where you come in: I want the horn from the smartest raptor around. \"King Reaperclaw\" leads a whole pack of intelligent raptors up on the bluffs north of Ratchet. Bring me his horn! And don't get ripped to ribbons like everyone else I've sent!", ["objectivesText"] = "Acquire King Reaperclaw's Horn . Progress: Did you get King Reaperclaw's horn , <name>? I need to test my first smart drink!", ["rewardXP"] = 740, ["rewardItems"] = { 5342, 46850, 49884, 59580, 59581, 59582, 131223 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3446, ["x"] = 0.678, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3446, ["x"] = 0.678, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[867] = { ["id"] = 867, ["name"] = "Harpy Raiders", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 875, 876, 14004, 14006, 29094, 29095, 29109, 29110, 29111, 29112 }, ["description"] = "Since you're here, <class>, perhaps you can help me with a small problem. The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers. The most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top. Take out Witchwing harpies of any kind in the Northwest and bring me 6 Witchwing Talons . That should be a good start...", ["objectivesText"] = "Collect 6 Witchwing Talons from Witchwing harpies. Progress: Cut up enough of them yet? Keep slicing and taking trophies. I want 8 Witchwing talons .", ["rewardGold"] = 105000, ["rewardXP"] = 740, ["rewardItems"] = { 5064 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3449, ["x"] = 0.305, ["y"] = 0.459 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3449, ["x"] = 0.305, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 54, ["flags"] = 0 } } },
[869] = { ["id"] = 869, ["name"] = "To Track a Thief", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 881, 905, 13991, 14066, 14067 }, ["description"] = "Animal tracks surround the wreckage, tracks made by enormous curved claws. They appear to be raptor tracks. Your first instinct is that raptor-riders assaulted the caravan, but the impressions aren't deep and there are no non-animal tracks to be seen. The tracks head northeast of here toward the east side of Thorn Hill. The answer to this mystery must lie in its shadow.", ["objectivesText"] = "The tracks lead to the east side of Thorn Hill. Follow them and see what you find.", ["rewardXP"] = 185, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3464, ["x"] = 0.668, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3464, ["x"] = 0.668, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 30, ["flags"] = 0 } } },
[870] = { ["id"] = 870, ["name"] = "The Forgotten Pools", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 877, 13988 }, ["description"] = "Have you felt the tremors, <class>? Something has cleaved this land in two. But we druids can sense other tremors, as well. Life is stirring in lands once dry and lifeless. The oases around the Crossroads are suddenly blooming. I can sense a power leaking its way to the surface, but from where? Is it related to the disaster that shattered the Barrens? We must find the source. Travel to the Forgotten Pools, northwest of the Crossroads. Search its waters for a source of power, then return here.", ["objectivesText"] = "Search the bottom of the Forgotten Pools northwest of the Crossroads.", ["rewardXP"] = 555, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3448, ["x"] = 0.495, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3448, ["x"] = 0.495, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 11, ["flags"] = 0 } } },
[871] = { ["id"] = 871, ["name"] = "In Defense of Far Watch", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 840, 872, 26642, 28494 }, ["description"] = "All the quilboars are our enemies, <name>. Some just prove to be more of a nuisance than others. The Razormane tribe has been attacking our supply caravans that roll through here from Orgrimmar. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us. Start just south of here, where they've been raiding our camps near the river. Seek them out, and slay them.", ["objectivesText"] = "Kill 8 Razormane Plunderers and 3 Razormane Hunters .", ["rewardXP"] = 740, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3337, ["x"] = 0.676, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3337, ["x"] = 0.676, ["y"] = 0.395 }, { ["mapID"] = 10, ["npcID"] = 3429, ["x"] = 0.486, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 0, ["flags"] = 0 } } },
[872] = { ["id"] = 872, ["name"] = "The Far Watch Offensive", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 840, 871, 26642, 28494 }, ["description"] = "Pigmen running amok right on the border of Durotar? Not on my watch! It is as they say, <name>: The best defense is crushing all who oppose you. One of my scouts followed the quilboar after the last caravan raid, so we know where to strike. Kreenig Snarlsnout is the mastermind behind the attacks along the river. Crush him, <class>. Defeat him and disembowel his forces so that the attacks on this camp cease. Search for a quilboar-infested cavern along the river, just south of our stables.", ["objectivesText"] = "Kill 5 Razormane Defenders , 5 Razormane Thornweavers , and Kreenig Snarlsnout. Take Snarlsnout's Tusk. Progress: Cut off the head of their leader, and chaos ensues, <name>. Learn this lesson well. It will aid you in the future.", ["rewardXP"] = 740, ["rewardItems"] = { 5063, 59542, 59543, 59544, 131224 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3337, ["x"] = 0.676, ["y"] = 0.395 }, { ["mapID"] = 10, ["npcID"] = 3429, ["x"] = 0.486, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3337, ["x"] = 0.676, ["y"] = 0.395 }, { ["mapID"] = 10, ["npcID"] = 3429, ["x"] = 0.486, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 1, ["flags"] = 0 } } },
[875] = { ["id"] = 875, ["name"] = "Harpy Lieutenants", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 867, 876, 14004, 14006, 29094, 29095, 29109, 29110, 29111, 29112 }, ["description"] = "The only way to stop the harpy raiders is to destroy their chain of command. The harpies are led by fearless lieutenants, Witchwing Slayers . If the Slayers fall, the rest will follow. Go to the Dry Hills and cut down the Witchwing Slayers . Make sure they die painfully, <name>. We want those harpy wenches to know the idiocy of picking fights with the Horde.", ["objectivesText"] = "Kill 6 Witchwing Slayers in the Dry Hills of the Northern Barrens . Progress: Do you have 6 Harpy Lieutenant Rings yet? Justice must be dealt to them for their vicious attacks on the Horde.", ["rewardGold"] = 105000, ["rewardXP"] = 740, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3449, ["x"] = 0.305, ["y"] = 0.459 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3449, ["x"] = 0.305, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 55, ["flags"] = 0 } } },
[876] = { ["id"] = 876, ["name"] = "Serena Bloodfeather", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 867, 875, 14004, 14006, 29094, 29095, 29109, 29110, 29111, 29112 }, ["description"] = "The harpies you've killed mentioned their matron, Serena Bloodfeather. Judging from their vile hatred toward the Horde, she must hold some kind of deep-seated grudge. You decide to hunt down Serena Bloodfeather and end matters once and for all.", ["objectivesText"] = "Slay Serena Bloodfeather and collect her head. Progress: You're not getting anything until I see Serena's head .", ["rewardXP"] = 925, ["rewardItems"] = { 5067, 59588, 59589, 59590 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3449, ["x"] = 0.305, ["y"] = 0.459 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3449, ["x"] = 0.305, ["y"] = 0.459 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.305, ["y"] = 0.459 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 56, ["flags"] = 0 } } },
[877] = { ["id"] = 877, ["name"] = "The Stagnant Oasis", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 870, 13988 }, ["description"] = "Can what's happening to the south happen here? Judging by what you found at the Forgotten Pools, these oases may be the key. Let's perform an experiment. Here, take these seeds I've collected from the summit here. They are dead and infertile, but carry them down to the Stagnant Oasis just below us. If there is a fissure there, then place the seeds within it... and observe. Report your findings back to Tonga at the Crossroads.", ["objectivesText"] = "Use the dried seeds to investigate the fissures in the Stagnant Oasis. Progress: Did Jerrik have any ideas? You look like you've been rummaging around in the mud...", ["rewardXP"] = 740, ["rewardItems"] = { 5066, 5068 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3448, ["x"] = 0.495, ["y"] = 0.586 }, { ["mapID"] = 10, ["npcID"] = 34626, ["x"] = 0.606, ["y"] = 0.853 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3448, ["x"] = 0.495, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 16, ["flags"] = 0 } } },
[880] = { ["id"] = 880, ["name"] = "Altered Beings", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["description"] = "It will be important to study both plant and animal life impacted by the oases and the unusual energies you've discovered. The Stagnant Oasis below us is home to a species of snapjaw turtles. Recently their population has exploded. Moreover, the once peaceful animals are growing aggressive, as I learned the hard way before trekking up here. <Jerrik holds up a bandaged finger.> I suspect they've been altered by the oases. Collect their shells and take them to Tonga at Crossroads for further study.", ["objectivesText"] = "Collect 6 Altered Snapjaw Shells from Snapjaws in the Stagnant Oasis. Progress: What else have you brought me?", ["rewardGold"] = 58650, ["rewardXP"] = 740, ["rewardItems"] = { 5098 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3448, ["x"] = 0.495, ["y"] = 0.586 }, { ["mapID"] = 10, ["npcID"] = 34626, ["x"] = 0.606, ["y"] = 0.853 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3448, ["x"] = 0.495, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 17, ["flags"] = 0 } } },
[881] = { ["id"] = 881, ["name"] = "Echeyakee", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 869, 905, 13991, 14066, 14067 }, ["description"] = "Whitemist, or ' Echeyakee ' in the tauren tongue, is the king of the savannah cats. He hunts with such stealth, they say he's like a thin, white mist on the earth. He kills so fast his prey have no time for fear or pain. The tauren say he is both mercy and death. <name>, I now set you on the path to hunt Echeyakee . His lair is just northwest of here, on the north side of a small mountain, among the bones of giant Kodo. Go. Blow this horn when you reach his lair. Blow the horn, and he will come.", ["objectivesText"] = "Blow your horn at Echeyakee 's lair to summon him. Slay or subdue him.", ["rewardXP"] = 925, ["rewardItems"] = { 10327 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 24, ["flags"] = 0 } } },
[887] = { ["id"] = 887, ["name"] = "Southsea Freebooters", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 887 }, ["description"] = "Gazlowe promised me a promotion if I can help him with Ratchet's pirate issues. The problem is these new buccaneers that sailed in and took over Fray Island, south of here. They're not just after our goods - they've got grudges to settle! The other night they even went after one of our war galleons. I've got plans in the works to deal with the situation, but Gazlowe wants to see quick results. Head over to Fray Island and start lopping off some heads, will you?", ["objectivesText"] = "Kill 8 Southsea Cutthroats or Privateers on Fray Island.", ["rewardGold"] = 210000, ["rewardXP"] = 740, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3391, ["x"] = 0.509, ["y"] = 0.72 }, { ["mapID"] = 10, ["npcID"] = 3453, ["x"] = 0.695, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3391, ["x"] = 0.509, ["y"] = 0.72 }, { ["mapID"] = 10, ["npcID"] = 3453, ["x"] = 0.695, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.509, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[891] = { ["id"] = 891, ["name"] = "A Captain's Vengeance", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 891 }, ["description"] = "Yet another ship from my fleet has been lost to those overzealous humans from Theramore! Their new Rear Admiral has parked himself right off the coast here. He's boarding or sinking any vessel that doesn't heave-to at his whim. Travel south along the Merchant Coast to his camp. Bring me the medals of the marines and deck hands. Execute his top Lieutenants, Pyre and Buckland. Lay waste to them as they have laid waste to my fleet!", ["objectivesText"] = "Collect 10 Theramore Medals from Theramore Marines and Deck Hands. Kill Lieutenants Pyre and Buckland. Progress: Fill my hand with medals from their dead and I will know that vengeance has been given to my fallen privateers.", ["rewardXP"] = 740, ["rewardItems"] = { 5078 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3339, ["x"] = 0.676, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3339, ["x"] = 0.676, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[895] = { ["id"] = 895, ["name"] = "WANTED: Cap'n Garvey", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 895 }, ["description"] = "WANTED ! \"Cap'n\" J. Garvey of the Maiden's Dagger Charged with piracy on the open seas, kidnapping, extortion, arson, slavery, et al. Garvey recently arrived in these waters leading a crew of Southsea Freebooters and was last seen assaulting Fray Island. Bring proof of death in an identifiable condition! -- Gazlowe", ["objectivesText"] = "Bring the head of Cap'n Garvey to Gazlowe in Ratchet. Progress: What's happening? Something I can help you with? Goods to ship, perhaps an engineering job?", ["rewardGold"] = 58650, ["rewardXP"] = 740, ["rewardItems"] = { 5084, 49446, 49543, 49548, 49560, 131225, 131226 }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3391, ["x"] = 0.509, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.509, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[899] = { ["id"] = 899, ["name"] = "Consumed by Hatred", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 899 }, ["description"] = "They murdered my wife. They burned my homestead. Since that awful night I have traveled these lands, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched. You, <class> - you could help me. Kill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.", ["objectivesText"] = "Collect 30 Quilboar Tusks . Progress: The quilboar will pay for this, <name>. I swear it.", ["rewardXP"] = 740, ["rewardItems"] = { 5085, 5314, 6477, 59539, 59540, 59541, 131227 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3432, ["x"] = 0.552, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3432, ["x"] = 0.552, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[903] = { ["id"] = 903, ["name"] = "Hunting the Huntress", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["description"] = "If you want to really demonstrate your bravery to me, let me send you after something that really bites. The savannah huntresses of the Barrens are as sly as they come. Tough, resourceful, quick... and deadly. They've been hassling our scouts recently around the outskirts of the town, especially to the northeast. Be wary as you hunt them, <name>, or you may find yourself no longer the predator, but instead the prey.", ["objectivesText"] = "Collect 5 Huntress Claws from Savannah Huntresses. Progress: How goes your hunt, <name>?", ["rewardGold"] = 105000, ["rewardXP"] = 740, ["rewardItems"] = { 5096 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 23, ["flags"] = 0 } } },
[905] = { ["id"] = 905, ["name"] = "Into the Raptor's Den", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["series"] = { 869, 881, 13991, 14066, 14067 }, ["description"] = "The hunt deepens, <name>. Now you must find and defeat your prey within its lair. Hunt the Sunscale raptors to the south, where they have built a warren amongst the hills just off of the road. Slay them and remove the feathers they wear. Place the feathers on the sunscale raptor nests to show their brethren you do not fear them! Be cautious, <class>. Raptors hunt in packs and will swarm you if you are not cautious.", ["objectivesText"] = "Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Sunscale Nests. Progress: Have you been to the nests, <name>?", ["rewardGold"] = 105000, ["rewardXP"] = 740, ["rewardItems"] = { 5165, 59549, 59550 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3338, ["x"] = 0.5, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 25, ["flags"] = 0 } } },
[932] = { ["id"] = 932, ["name"] = "Twisted Hatred", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 475, 476, 483, 486, 487, 488, 489, 918, 919, 922, 923, 930, 931, 932, 933, 935, 937, 997, 2438, 2459, 2499, 2518, 2541, 2561, 7383, 13945, 13946, 14005, 14039 }, ["description"] = "I must warn you, <name>, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home. He is called Lord Melenas. He resides in the nearby cave of Fel Rock, to the north, where he has gathered a large group of grell warriors. His heart is black as night, and he plots something most foul. You must find him within his nearby cave just to the north of here, and bring me his head.", ["objectivesText"] = "Retrieve the head of Lord Melenas. Progress: Did you kill Lord Melenas yet? It is vital that he be taken care of quickly and quietly, <name>. His continued existence is an embarrassment to us all.", ["rewardXP"] = 200, ["rewardItems"] = { 2571, 5221, 5419, 54867, 131228 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 3567, ["x"] = 0.555, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 3567, ["x"] = 0.555, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 568, ["name"] = "Teldrassil", ["orderIndex"] = 11, ["flags"] = 0 } } },
[933] = { ["id"] = 933, ["name"] = "Teldrassil: The Coming Dawn", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 475, 476, 483, 486, 487, 488, 489, 918, 919, 922, 923, 930, 931, 932, 933, 935, 937, 997, 2438, 2459, 2499, 2518, 2541, 2561, 7383, 13945, 13946, 14005, 14039 }, ["series"] = { 935, 7383, 14005, 14039 }, ["description"] = "There is one last moonwell that I would like you to visit. It is directly south of here, on the shores of the Pools of Arlithrien. Be wary as you seek out the well, and keep your weapons close at hand. I sense a growing corruption from the boughs of southern Teldrassil . When you have the water, I want you to bring it to a familiar face that you'll see at the pools. She wishes to battle the corruption, and has asked for you personally.", ["objectivesText"] = "Fill the Tourmaline Phial . Progress: It is good to see you again, <name>. I see you have succeeded in collecting the waters of the moonwells on behalf of Corithras Moonrage . I hope you have learned much along the way.", ["rewardXP"] = 200, ["rewardItems"] = { 5621, 5645 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 3515, ["x"] = 0.459333, ["y"] = 0.482667 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 1992, ["x"] = 0.425, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.459333, ["y"] = 0.482667 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 568, ["name"] = "Teldrassil", ["orderIndex"] = 25, ["flags"] = 0 } } },
[941] = { ["id"] = 941, ["name"] = "Planting the Heart", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 941 }, ["description"] = "I have removed that foul moss from the heart, but it remains tainted... Try placing the heart in my planter. It is filled with a nutritive soil that may cleanse and heal the heart.", ["objectivesText"] = "Plant the Tainted Heart in Denalan's Planter . Progress: This planter is filled with soil, specially prepared by Denalan .", ["rewardXP"] = 200, ["rewardItems"] = { 5217, 5218 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 2080, ["x"] = 0.518, ["y"] = 0.519 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.519 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Paladin" },
[1168] = { ["id"] = 1168, ["name"] = "Army of the Black Dragon", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 1168, 1201, 1202, 9437, 25051, 26682, 27183, 27184, 27186, 27188, 27189, 27190, 27191, 27229, 27244, 27253, 27254, 27255, 27256, 27257, 27258, 27259, 27260, 27261, 27292, 27293, 27294, 27295, 27296, 27297, 27306, 27407, 27408, 27409, 27410, 27411, 27414, 27415, 27416, 27417, 27418 }, ["description"] = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres. Black dragons kill many ogre. Kill Tharg 's wife. Mok'Morokk tell us to run. Make us come here. Ogre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk. Me call Stonemaul Ruins home. Me like it in the south. This place not home. Help ogres fight army of the black dragon. Me want revenge. Me want to go home.", ["objectivesText"] = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts , 10 Firemane Ash Tails , and 5 Firemane Scalebanes .", ["rewardXP"] = 2090, ["rewardItems"] = { 9706, 10702 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 4502, ["x"] = 0.372, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 4502, ["x"] = 0.372, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.372, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70, ["questLines"] = { { ["id"] = 526, ["name"] = "Dustwallow Marsh", ["orderIndex"] = 70, ["flags"] = 0 } } },
[1201] = { ["id"] = 1201, ["name"] = "Theramore Spies", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 1168, 1201, 1202, 9437, 25051, 26682, 27183, 27184, 27186, 27188, 27189, 27190, 27191, 27229, 27244, 27253, 27254, 27255, 27256, 27257, 27258, 27259, 27260, 27261, 27292, 27293, 27294, 27295, 27296, 27297, 27306, 27407, 27408, 27409, 27410, 27411, 27414, 27415, 27416, 27417, 27418 }, ["series"] = { 1202 }, ["description"] = "The Horde and Alliance hold an uneasy truce. Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top! Now is the chance to do just that. Alliance infiltrators have taken positions east of Brackenwall Village. They spy on the village and report our movements to Theramore, which we cannot allow. Hunt down the infiltrators and slay them. Send a clear message to their superiors that we will not tolerate their spies' presence!", ["objectivesText"] = "Kill 9 Theramore Infiltrators , then return to Nazeer Bloodpike in Brackenwall Village.", ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 4791, ["x"] = 0.352, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 4791, ["x"] = 0.352, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70, ["questLines"] = { { ["id"] = 526, ["name"] = "Dustwallow Marsh", ["orderIndex"] = 8, ["flags"] = 0 } } },
[1202] = { ["id"] = 1202, ["name"] = "The Theramore Docks", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 1168, 1201, 1202, 9437, 25051, 26682, 27183, 27184, 27186, 27188, 27189, 27190, 27191, 27229, 27244, 27253, 27254, 27255, 27256, 27257, 27258, 27259, 27260, 27261, 27292, 27293, 27294, 27295, 27296, 27297, 27306, 27407, 27408, 27409, 27410, 27411, 27414, 27415, 27416, 27417, 27418 }, ["series"] = { 1201 }, ["description"] = "<name>, two of our spies were sent to steal documents from a ship at the Theramore docks. They gained the papers but were discovered, and were forced to throw the documents into the sea. One spy later escaped, but was unable to recover the prize. He reported his failure to me, and I now charge the task to you. The documents are in a footlocker, in the waters somewhere beneath the Theramore docks. Find those documents, <name>, and bring them to me.", ["objectivesText"] = "Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village. Progress: Did you find the documents, <name>? They hold information vital to the stability of the Alliance and, hence, vital to the security of the Horde.", ["rewardXP"] = 2090, ["rewardItems"] = { 5882 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 4791, ["x"] = 0.352, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 4791, ["x"] = 0.352, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70, ["questLines"] = { { ["id"] = 526, ["name"] = "Dustwallow Marsh", ["orderIndex"] = 55, ["flags"] = 0 } } },
[1204] = { ["id"] = 1204, ["name"] = "Mudrock Soup and Bugs", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 1204 }, ["series"] = { 1258 }, ["description"] = "I'm working on a dish I call \"Mudrock Soup and Bugs.\" I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh ! So, <name>, can you do some hunting for me? First, I need the tongues of Mudrock turtles. You can find Mudrocks along the coast, mostly around the bay. But I don't want just any tongues! I hear that the tongues of some Mudrocks are forked... They say the forked tongues have a distinct flavor, and I want that flavor in my dish...", ["objectivesText"] = "Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore. Progress: Did you get the forked tongues?", ["rewardXP"] = 2090, ["rewardItems"] = { 5883, 86570 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 4794, ["x"] = 0.682, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 4794, ["x"] = 0.682, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard" },
[1222] = { ["id"] = 1222, ["name"] = "Stinky's Escape", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster", "escort" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 1222 }, ["description"] = "Great, finally something that doesn't want to eat me! I need help handling the critters around here, and you fit the mold, <buddy/lady>. The cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves. I guess he thinks they're tasty. Anyway, while looking for a bogbean plant... I got myself surrounded! Can you help me out of here, and watch my back as I look for the bogbean?", ["objectivesText"] = "Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 3825 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 4880, ["x"] = 0.47625, ["y"] = 0.20075 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 4794, ["x"] = 0.682, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.47625, ["y"] = 0.20075 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard" },
[1258] = { ["id"] = 1258, ["name"] = "... and Bugs", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 1258 }, ["series"] = { 1204 }, ["description"] = "Another component of my new recipe is the shelled leg of a giant crab. And the crabs they have in Dustwallow -- spiny rock crawlers they call them -- will be perfect! The shell of the crab leg is a key element of the dish's presentation so I need pristine, unscarred legs. An adult crab might only have one or two such legs, and I need a lot in order to research my dish. Head on over to the rocks surrounding Theramore and get me those legs!", ["objectivesText"] = "Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore. Progress: My research with the Mudrock tongues is progressing nicely. I trust your crab hunt goes well?", ["rewardGold"] = 573000, ["rewardXP"] = 2090, ["rewardItems"] = { 5938, 56851, 56852, 56853, 56854, 57843, 57844, 166846, 166970, 166971, 245711, 245712 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 4794, ["x"] = 0.682, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 4794, ["x"] = 0.682, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard" },
[1270] = { ["id"] = 1270, ["name"] = "Stinky's Escape", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster", "escort" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 1270 }, ["description"] = "Great, finally something that doesn't want to eat me!! I need help handling the critters around here, and you fit the mold, <buddy/lady>. A goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am. Too bad I got myself surrounded before I found the bogbean! Can you help me out of here, and watch my back as I look for Mebok's plant?", ["objectivesText"] = "Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 3825, 48112 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 4880, ["x"] = 0.47625, ["y"] = 0.20075 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3446, ["x"] = 0.678, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.47625, ["y"] = 0.20075 }, ["mapCandidates"] = { ["npc"] = { 10, 70 }, ["zone"] = { 15 } }, ["questType"] = "standard" },
[1271] = { ["id"] = 1271, ["name"] = "Feast at the Blue Recluse", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 1271 }, ["rewardItems"] = { 5951 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 1141, ["x"] = 0.515, ["y"] = 0.9345 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1141, ["x"] = 0.515, ["y"] = 0.9345 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.9345 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[1454] = { ["id"] = 1454, ["name"] = "The Karnitol Shipwreck", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 405, ["mapID"] = 66, ["storyline"] = { 1454, 1455, 1456, 14256, 14257, 14260, 14264, 14268, 14282, 14284, 14292, 14301, 14302, 14304, 14305, 14306, 14307, 14309, 14311, 14312, 14314, 14316, 14318, 14325, 14327, 14328, 14329, 14330, 14332, 14333, 14354, 14361, 14363, 14364, 14373, 14374, 14378, 14379, 14380, 14381, 14384, 14387, 14393, 14394 }, ["series"] = { 1455, 1456 }, ["description"] = "Greetings, friend. Have yerself a seat here... My first order of business is for the mage Karnitol--a noble of some sort in Stormwind. Seems his ship was attacked by sea giants while off the coast in the northwest of Desolace . He and his servants tried to bring one of his more valuable chests ashore, but when the sea giants attacked in droves, he chose to abandon it and teleport himself and his servants to safety. He wants us to find the chest and its contents, and return it to him in Stormwind.", ["objectivesText"] = "Find Karnitol's Chest in Desolace .", ["rewardXP"] = 1415, ["rewardItems"] = { 55948, 55949, 55950, 131231 }, ["starts"] = { { ["mapID"] = 66, ["npcID"] = 5638, ["x"] = 0.662, ["y"] = 0.096 } }, ["coords"] = { ["mapID"] = 66, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.096 }, ["mapCandidates"] = { ["npc"] = { 66 }, ["zone"] = { 405 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 66, ["db2QuestSortName"] = "Pickpocketing", ["questLines"] = { { ["id"] = 520, ["name"] = "Desolace", ["orderIndex"] = 6, ["flags"] = 0 } } },
[1455] = { ["id"] = 1455, ["name"] = "The Karnitol Shipwreck", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 405, ["mapID"] = 66, ["storyline"] = { 1454, 1455, 1456, 14256, 14257, 14260, 14264, 14268, 14282, 14284, 14292, 14301, 14302, 14304, 14305, 14306, 14307, 14309, 14311, 14312, 14314, 14316, 14318, 14325, 14327, 14328, 14329, 14330, 14332, 14333, 14354, 14361, 14363, 14364, 14373, 14374, 14378, 14379, 14380, 14381, 14384, 14387, 14393, 14394 }, ["series"] = { 1454, 1456 }, ["description"] = "You take a few moments to figure out what pried the chest open, and you notice along the sides and top of the chest, long, deep scratches that reveal that something other than a man or giant took interest in it. The marks don't appear as if they were caused by dagger or sword. After going through the chest you find it to be completely empty. Not having another course of action, you close the chest and prepare to leave. Kreldig will be disappointed.", ["objectivesText"] = "Return to Kreldig Ungor in Desolace .", ["rewardXP"] = 710, ["rewardItems"] = { 55948, 55949, 55950, 131231 }, ["ends"] = { { ["mapID"] = 66, ["npcID"] = 5638, ["x"] = 0.662, ["y"] = 0.096 } }, ["coords"] = { ["mapID"] = 66, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.096 }, ["mapCandidates"] = { ["npc"] = { 66 }, ["zone"] = { 405 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 66, ["db2QuestSortName"] = "Pickpocketing", ["questLines"] = { { ["id"] = 520, ["name"] = "Desolace", ["orderIndex"] = 7, ["flags"] = 0 } } },
[1456] = { ["id"] = 1456, ["name"] = "The Karnitol Shipwreck", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 405, ["mapID"] = 66, ["storyline"] = { 1454, 1455, 1456, 14256, 14257, 14260, 14264, 14268, 14282, 14284, 14292, 14301, 14302, 14304, 14305, 14306, 14307, 14309, 14311, 14312, 14314, 14316, 14318, 14325, 14327, 14328, 14329, 14330, 14332, 14333, 14354, 14361, 14363, 14364, 14373, 14374, 14378, 14379, 14380, 14381, 14384, 14387, 14393, 14394 }, ["series"] = { 1454, 1455 }, ["description"] = "Intriguing. Well, we might not be without hope quite yet. Along that same coast, but to the north near Ranazjar Isle, there're night elf ruins at the bottom of the ocean. A tribe of naga, the Slitherblade, make that their home. I think that'd be our best bet. If a scouting party went that far south, then they must've been pretty powerful. If you're gonna find Karnitol's belongings, I'd start with the more powerful naga: the tidehunters or sea witches.", ["objectivesText"] = "Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace . Progress: No offense to whoever Nijel is, but this camp ain't the most comfortable place I've spent a night, if you know what I mean, <name>.", ["rewardXP"] = 1415, ["rewardItems"] = { 6245, 34130, 55948, 55949, 55950, 131231 }, ["starts"] = { { ["mapID"] = 66, ["npcID"] = 5638, ["x"] = 0.662, ["y"] = 0.096 } }, ["ends"] = { { ["mapID"] = 66, ["npcID"] = 5638, ["x"] = 0.662, ["y"] = 0.096 } }, ["coords"] = { ["mapID"] = 66, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.096 }, ["mapCandidates"] = { ["npc"] = { 66 }, ["zone"] = { 405 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 66, ["db2QuestSortName"] = "Pickpocketing", ["questLines"] = { { ["id"] = 520, ["name"] = "Desolace", ["orderIndex"] = 8, ["flags"] = 0 } } },
[1918] = { ["id"] = 1918, ["name"] = "The Befouled Element", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 1918 }, ["series"] = { 824 }, ["description"] = "The slain elemental has produced an intensely glowing globe of water. The contents of the globe are, at best, disgusting. It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe. It's not exactly common knowledge who might be interested in such a find; perhaps Mastok Wrilehiss at Splintertree Post, might have an idea.", ["objectivesText"] = "Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale . Progress: Yeah, what do you need?", ["rewardXP"] = 255, ["rewardItems"] = { 16408 }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12737, ["x"] = 0.74, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["startItems"] = { 16408 } },
[4021] = { ["id"] = 4021, ["name"] = "Counterattack!", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["description"] = "The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened. I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance. My latest report was that, even now, they move against these bunkers, from the west! Face the Kolkar invaders, and end their threat in the Barrens. Kill them until their leader, Warlord Krom'zar, appears. Defeat him and bring me a piece of his banner as proof. We're counting on you, <name>.", ["objectivesText"] = "Kill Kolkar centaur until Krom'zar appears, then slay him and take a Piece of Krom'zar's Banner . Progress: Do you have the banner?", ["rewardGold"] = 210000, ["rewardXP"] = 925, ["rewardItems"] = { 11227, 59591, 59592, 59593 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3389, ["x"] = 0.378, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 21, ["flags"] = 0 } } },
[5041] = { ["id"] = 5041, ["name"] = "Supplies for the Crossroads", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 845, 848, 850, 851, 852, 867, 869, 870, 871, 872, 875, 876, 877, 880, 881, 903, 905, 4021, 5041, 13949, 13961, 13963, 13968, 13969, 13970, 13971, 13975, 13988, 13998, 13999, 14003, 14004, 14006, 14034, 14038, 14042, 14045, 14046, 14049, 14050, 14052, 14056, 14057, 14063, 14066, 14067, 14072, 26769, 29015, 29021, 29022, 29023, 29024, 29026, 29027, 29086, 29094, 29095, 29109, 29110, 29111, 29112 }, ["description"] = "Whatever has happened in Southern Barrens is causing some of the quilboar tribes to flee our direction. The displaced Razormane in particular grow desperate, and their attacks grow bolder. I've lost two caravans this week alone! Our warriors at the Crossroads desperately need those supplies, and I'm not about to let the quilboar grow fat off of their misdeeds. Find the missing supply crates and bring them to me. I'd search the quilboar hovel south of here, along the river.", ["objectivesText"] = "Collect 5 Crossroads Supply Crates from inside the Razormane cave. Progress: How goes your search for the supplies, <name>? I trust the quilboar fall under your strength easily.", ["rewardGold"] = 286500, ["rewardXP"] = 740, ["rewardItems"] = { 12708 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 34258, ["x"] = 0.558, ["y"] = 0.398667 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3429, ["x"] = 0.486, ["y"] = 0.595 }, { ["mapID"] = 10, ["npcID"] = 34258, ["x"] = 0.558, ["y"] = 0.398667 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.398667 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 509, ["name"] = "Northern Barrens", ["orderIndex"] = 2, ["flags"] = 0 } } },
[5421] = { ["id"] = 5421, ["name"] = "Fish in a Bucket", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 405, ["mapID"] = 66, ["storyline"] = { 5421, 5581, 14188, 14189, 14191, 14195, 14196, 14198, 14223, 14225, 14227, 14232, 14256, 14257, 14260, 14264, 14268, 14282, 14284, 14292, 14301, 14302, 14304, 14305, 14306, 14307, 14309, 14311, 14312, 14314, 14316, 14318, 14325, 14327, 14328, 14329, 14330, 14332, 14333, 14334, 14335, 14339, 14342, 14343, 14346, 14360, 14393, 14394 }, ["description"] = "I'll reward anyone who makes my life a bit easier... I enjoy doing as little as possible, mon! Below the docks here in Shadowprey Village, I've many shellfish traps. If you're kind enough to do my work and collect me my shellfish , then I'll reward you with something you want... get my drift mon?", ["objectivesText"] = "Jinar'Zillen wants you to collect 5 Shellfish from the traps near Shadowprey Village. Progress: Ya got mah shellfish , mon?", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 6367, 13545, 13546 }, ["starts"] = { { ["mapID"] = 66, ["npcID"] = 11317, ["x"] = 0.225, ["y"] = 0.729 } }, ["ends"] = { { ["mapID"] = 66, ["npcID"] = 11317, ["x"] = 0.225, ["y"] = 0.729 } }, ["coords"] = { ["mapID"] = 66, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.729 }, ["mapCandidates"] = { ["npc"] = { 66 }, ["zone"] = { 405 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 66, ["db2QuestSortName"] = "Pickpocketing", ["questLines"] = { { ["id"] = 520, ["name"] = "Desolace", ["orderIndex"] = 54, ["flags"] = 0 } } },
[5501] = { ["id"] = 5501, ["name"] = "Bone Collector", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 405, ["mapID"] = 66, ["storyline"] = { 5501 }, ["description"] = "We're sitting on a goldmine here, I tell you - a goldmine! Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them. There's a caravan that comes by and picks up my Kodo bones and then sells them at Shadowprey Village. If you can travel to the kodo graveyard south of here and bring me ten Kodo bones , I'll give you something in return. Is it a deal?", ["objectivesText"] = "Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut. Progress: Do you have the bones? The caravan will be here any moment. I need just ten more kodo bones to reach a career high. A career high, I tell you!", ["rewardXP"] = 1060, ["rewardItems"] = { 13703 }, ["starts"] = { { ["mapID"] = 66, ["npcID"] = 11438, ["x"] = 0.622, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 66, ["npcID"] = 11438, ["x"] = 0.622, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 66, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 66 }, ["zone"] = { 405 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Pickpocketing" },
[5561] = { ["id"] = 5561, ["name"] = "Kodo Roundup", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 405, ["mapID"] = 66, ["storyline"] = { 5561 }, ["description"] = "Bibbly thinks he is the only goblin in Desolace who knows how to make money. Well, the only caravan brave enough to travel these parts relies on me. Ever since I learned how to rejuvenate and control aged kodos with my kodo kombobulator , the caravan owner Cork, Rigger, and I entered a partnership. Take the kombobulator and use it on any ancient or aged kodos; it will jolt the beast into a tamed kodo and force it to follow you. Once you have a kodo tamed, bring it back to me.", ["objectivesText"] = "Bring 3 Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp. Progress: The caravan will be here shortly; do you have the newly tamed kodos I was asking for?", ["rewardXP"] = 1060, ["rewardItems"] = { 13892, 15697 }, ["starts"] = { { ["mapID"] = 66, ["npcID"] = 11596, ["x"] = 0.608, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 66, ["npcID"] = 11596, ["x"] = 0.608, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 66, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 66 }, ["zone"] = { 405 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Pickpocketing" },
[5581] = { ["id"] = 5581, ["name"] = "Portals of the Legion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 405, ["mapID"] = 66, ["storyline"] = { 5421, 5581, 14188, 14189, 14191, 14195, 14196, 14198, 14223, 14225, 14227, 14232, 14256, 14257, 14260, 14264, 14268, 14282, 14284, 14292, 14301, 14302, 14304, 14305, 14306, 14307, 14309, 14311, 14312, 14314, 14316, 14318, 14325, 14327, 14328, 14329, 14330, 14332, 14333, 14334, 14335, 14339, 14342, 14343, 14346, 14360, 14393, 14394 }, ["description"] = "Here it is - the Hand of Iruxos . Got it from one of the Burning Blade leaders myself. You must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do. With the demon threat increasing we must close these portals to stem the tide of demons to this world.", ["objectivesText"] = "Banish 6 Portals at Mannoroc Coven and return to Felgur Twocuts at Ghost Walker Post.", ["rewardGold"] = 105000, ["rewardXP"] = 1770, ["rewardItems"] = { 14547, 55936, 55937, 55938, 55939, 55940, 55941, 131233, 131352 }, ["starts"] = { { ["mapID"] = 66, ["npcID"] = 5395, ["x"] = 0.562, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 66, ["npcID"] = 5395, ["x"] = 0.562, ["y"] = 0.595 }, { ["mapID"] = 66, ["npcID"] = 11624, ["x"] = 0.258, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 66, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 66 }, ["zone"] = { 405 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 66, ["db2QuestSortName"] = "Pickpocketing", ["questLines"] = { { ["id"] = 520, ["name"] = "Desolace", ["orderIndex"] = 38, ["flags"] = 0 } } },
[5713] = { ["id"] = 5713, ["name"] = "One Shot. One Kill.", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 5713 }, ["description"] = "I was traveling to Lor'danel with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready. I would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can. Should we survive, I will be able to deliver my message to Lor'danel, while you speak with Onaeya at Maestra's Post to inform her of this incident.", ["objectivesText"] = "Protect Sentinel Aynasha , then speak with Onaeya at Maestra's Post in Ashenvale.", ["rewardGold"] = 683200, ["rewardXP"] = 740, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 11711, ["x"] = 0.3895, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 11806, ["x"] = 0.266, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 62, 63 }, ["zone"] = { 148 } }, ["questType"] = "standard" },
[6031] = { ["id"] = 6031, ["name"] = "Runecloth", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 6031 }, ["description"] = "In Timbermaw, we are content. We do not like strangers. This is good for us, but it is bad for trade. Not long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak. runecloth is rare among us, but the cloak was so fine my people want me to make more runecloth clothing. Will you bring me runecloth ? If you bring me enough, then I will give you something in trade.", ["objectivesText"] = "Bring 30 Runecloth to Meilosh in Timbermaw Hold. Progress: Do you have the runecloth ? My people are eager for more items of runecloth !", ["rewardXP"] = 2090, ["rewardItems"] = { 14047, 15822, 15823 }, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 11557, ["x"] = 0.386667, ["y"] = 0.479333 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 11557, ["x"] = 0.386667, ["y"] = 0.479333 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.386667, ["y"] = 0.479333 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard" },
[6132] = { ["id"] = 6132, ["name"] = "Get Me Out of Here!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 405, ["mapID"] = 66, ["storyline"] = { 6132 }, ["description"] = "Get me out of here! I came up to the Valley of Spears to talk to the Maraudines. I thought I could do a little business with them... but they don't want to talk! I think they want to eat me! Get me out of here and my brother Hornizz will pay you big! He's at our camp next to the kodo graveyard, to the east. Let's hurry, <name>. Not two minutes ago I heard some centaurs talking about getting wood for their cookpot...", ["objectivesText"] = "Escort Melizza Brimbuzzle .", ["rewardGold"] = 341600, ["rewardXP"] = 1060, ["rewardItems"] = { 37047, 37049, 37528, 57360, 57361, 57362, 181501, 181502, 181507, 181625, 181626, 181645, 181647, 181649, 181688, 181689, 181691, 181693, 181697, 181865, 183490, 184195, 184305, 184772, 184773, 184774, 184775, 184776, 211279 }, ["starts"] = { { ["mapID"] = 66, ["npcID"] = 12277, ["x"] = 0.341, ["y"] = 0.551667 } }, ["ends"] = { { ["mapID"] = 66, ["npcID"] = 6019, ["x"] = 0.478, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 66, ["source"] = "quest_giver", ["x"] = 0.341, ["y"] = 0.551667 }, ["mapCandidates"] = { ["npc"] = { 66 }, ["zone"] = { 405 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Pickpocketing" },
[6134] = { ["id"] = 6134, ["name"] = "Ghost-o-plasm Round Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 405, ["mapID"] = 66, ["storyline"] = { 6134 }, ["description"] = "There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts. Sounds scary, doesn't it? Well think how scary it is to the Magram! If we captured ghost energy from that place, I bet it'd be worth plenty to those centaurs. Here, take this crate of ghost magnets . If you place one between the two big skeletons in the valley, the Dead Goliaths, then ghosts will wander to it. Distance yourself, take out the ghosts and get their ghost-o-plasm --that's what we'll sell to the Magram.", ["objectivesText"] = "Collect 8 Ghost-o-plasms . Progress: Where's my ghost-o-plasm , <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 1060, ["rewardItems"] = { 15848, 15849, 15864, 15865 }, ["starts"] = { { ["mapID"] = 66, ["npcID"] = 6019, ["x"] = 0.478, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 66, ["npcID"] = 6019, ["x"] = 0.478, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 66, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 66 }, ["zone"] = { 405 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Pickpocketing" },
[6441] = { ["id"] = 6441, ["name"] = "Satyr Horns", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 6441 }, ["description"] = "Heya! I've been traveling through Ashenvale , heading towards Ratchet, and decided to make a stop here at Splintertree. I'm always looking for an opportunity, and it seems that satyr horns are in high demand in Ratchet these days. After asking around here, it seems that the satyrs in Night Run, Satyrnaar, and Xavian all have the type of horns I am looking for. I'm no match for those satyrs... but you look like you might be! Tell you what, you collect the horns for me and I'll make it worth your time.", ["objectivesText"] = "Collect 16 Satyr Horns for Pixel in Splintertree Post. Progress: I hope you can be quick about getting those horns, <name>. I'm heading back to Ratchet soon!", ["rewardGold"] = 105000, ["rewardXP"] = 1010, ["rewardItems"] = { 5481, 23797 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 12724, ["x"] = 0.738, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12724, ["x"] = 0.738, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[6442] = { ["id"] = 6442, ["name"] = "Naga at the Zoram Strand", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 719, ["mapID"] = 63, ["storyline"] = { 6442, 6641, 13618, 13619, 13620, 13621, 13628, 13640, 13651, 13653, 13712, 13730, 13751, 13797, 13798, 13803, 13805, 13808, 13815, 13841, 13842, 13865, 13870, 13871, 13873, 13879, 13888, 13890, 13901, 13920, 13936, 13942, 13943, 13944, 13947, 13958, 13962, 13974, 13977, 13980, 13983, 26890 }, ["description"] = "There is evil lurking here along the coast, <race>. It is the resting place of the doomed city of Zoram, long destroyed and submerged beneath the seas. Lost, and nearly forgotten. Now, the naga have returned, and for what reason we do not know. But reason matters little; we must defend the land we have worked so hard to claim as our own. Return to me with 20 of their heads! Throw the naga back to the depths!", ["objectivesText"] = "Bring 20 Wrathtail Heads to Marukai along the Zoram Strand. Progress: The naga increase in numbers, <name>. Please complete this task for me.", ["rewardXP"] = 1010, ["rewardItems"] = { 5490 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 12719, ["x"] = 0.126, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12719, ["x"] = 0.126, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.126, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 719 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 516, ["name"] = "Ashenvale, Horde", ["orderIndex"] = 24, ["flags"] = 0 } } },
[6462] = { ["id"] = 6462, ["name"] = "Troll Charm", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 6462 }, ["description"] = "My kinfolk were traveling here with many sacred troll charms , but the Thistlefur furbolgs attacked and killed them before they reached Zoram'gar! Those vile furbolgs! I miss my brothers and sisters who were killed, but we will meet again in the afterlife. However, their troll charms hold great value in this world. It is an outrage that the furbolgs have them! <name>, you must retrieve the charms! They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.", ["objectivesText"] = "Bring 8 Troll Charms to Mitsuwa at Hellscream's Watch. Progress: Did you find the charms, <name>? Every moment the furbolgs possess those sacred items, my blood boils with rage!", ["rewardGold"] = 105000, ["rewardXP"] = 1010, ["rewardItems"] = { 16602 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 12721, ["x"] = 0.388, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12721, ["x"] = 0.388, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[6482] = { ["id"] = 6482, ["name"] = "Freedom to Ruul", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 6482 }, ["description"] = "Eh? Who are you? <name>? You're no furbolg. They are cursed! They thought I was a bear and captured me, and now they starve me! My strength is failing... Help me escape, then speak with my sister Yama at the Splintertree Post to the east. <name>! I must escape!", ["objectivesText"] = "Escort Ruul, then speak with Yama Snowhoof in Splintertree Post.", ["rewardGold"] = 341600, ["rewardXP"] = 1265, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 12818, ["x"] = 0.399667, ["y"] = 0.341333 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12837, ["x"] = 0.74, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.399667, ["y"] = 0.341333 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[6503] = { ["id"] = 6503, ["name"] = "Ashenvale Outrunners", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 6503 }, ["description"] = "Blasted elves! Dey knew right where to hit us! It was dem outrunners... I tried to warn 'em that we were being spied on, but no one listened. Now look at us - cooped up here like chickens! Never too late for vengeance, mon! Hunt 'em down and make 'em pay for what they done!", ["objectivesText"] = "Kill 9 Ashenvale Outrunners .", ["rewardGold"] = 58650, ["rewardXP"] = 1010, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 12867, ["x"] = 0.735, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12867, ["x"] = 0.735, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[6544] = { ["id"] = 6544, ["name"] = "Torek's Assault", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 6544 }, ["description"] = "Hey! <class>! Come here! My raiders and I are about to attack the Silverwing Outpost to the west. Our target is its leader, Duriel Moonfire. Scouts report the outpost is defended heavily with sentinels and warriors. The battle will be glorious! Do you want to share in the glory, <name>, and aid us? If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree. What do you say. Are you with us?", ["objectivesText"] = "Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.", ["rewardGold"] = 341600, ["rewardXP"] = 1265, ["rewardItems"] = { 16889, 16890, 156956 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 12858, ["x"] = 0.663429, ["y"] = 0.746571 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12877, ["x"] = 0.73, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.663429, ["y"] = 0.746571 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[6621] = { ["id"] = 6621, ["name"] = "King of the Foulweald", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 6621 }, ["series"] = { 13967 }, ["description"] = "My research has paid off. I believe that with a show of force, we can diminish the furbolgs' aggressiveness. Take this banner a short ways northeast and place it on their totem mound. They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe. Bring me the totem he carries. Gather your allies, <name>. This is no task for a single <class>.", ["objectivesText"] = "Place Senani's Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner. Defeat Chief Murgut and bring Murgut's Totem to Senani at Silverwind Refuge. Progress: Did you defeat Chief Murgut, <name>? Did you retrieve his foulweald totem?", ["rewardGold"] = 309800, ["rewardXP"] = 1265, ["rewardItems"] = { 16972, 16976, 17005, 17006, 56706, 56707, 131234, 137663 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 12696, ["x"] = 0.498, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12696, ["x"] = 0.498, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[6641] = { ["id"] = 6641, ["name"] = "Vorsha the Lasher", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 6442, 6641, 13618, 13619, 13620, 13621, 13628, 13640, 13651, 13653, 13712, 13730, 13751, 13797, 13798, 13803, 13805, 13808, 13815, 13841, 13842, 13865, 13870, 13871, 13873, 13879, 13888, 13890, 13901, 13920, 13936, 13942, 13943, 13944, 13947, 13958, 13962, 13974, 13977, 13980, 13983, 26890 }, ["description"] = "Vorsha the Lasher... the fiendish hydra that roams the seas... She has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path. But I am ready, <name>. I have prepared to best the hydra and end these attacks on Zoram'gar. The naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger. We will need help, so be sure to bring some strong allies.", ["objectivesText"] = "Defeat Vorsha the Lasher.", ["rewardXP"] = 1265, ["rewardItems"] = { 17692 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 12717, ["x"] = 0.117111, ["y"] = 0.314222 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 12863, ["x"] = 0.124, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.117111, ["y"] = 0.314222 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 516, ["name"] = "Ashenvale, Horde", ["orderIndex"] = 28, ["flags"] = 0 } } },
[7737] = { ["id"] = 7737, ["name"] = "Gaining Even More Acceptance", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 51, ["mapID"] = 32, ["storyline"] = { 7737 }, ["objectivesText"] = "Progress: You've worked your way up through the Brotherhood's corporate hierarchy, <race>. We have begun to look favorably upon you. Quite an accomplishment! If you're interested in more work and earning more respect amongst us, listen up. We can refine our fiery flux by adding a simple Dark Iron residue to the mix. This Dark Iron residue can be found in Blackrock Depths. Bring me all the Dark Iron residue you find!", ["rewardItems"] = { 11370, 18945 }, ["starts"] = { { ["mapID"] = 32, ["npcID"] = 14624, ["x"] = 0.385, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 32, ["npcID"] = 14624, ["x"] = 0.385, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 32, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 32 }, ["zone"] = { 51 } }, ["questType"] = "dungeon" },
