[8277] = { ["id"] = 8277, ["name"] = "Deadly Desert Venom", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8277 }, ["description"] = "Beetix Ficklespragg at your service! My cousin Noggle makes a living gathering rare herbs for Cenarion Hold alchemists. Or used to, anyway. He came back from his last trip with a strong poison running though his veins. I've managed to slow down the venom, but to fully neutralize it I need poison samples from whatever stung him. Noggle arrived from the north, so I'd bet my shirt stonelash scorpids or sand skitterers did it. Bring me some stingers and fangs and I'll try to make an antidote for him.", ["objectivesText"] = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 8 Stonelash Scorpid Stingers and 8 Sand Skitterer Fangs . Return to her when you have completed the task. Progress: Are you done collecting those samples? We could lose Noggle any minute now!", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 20373, 20376 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15189, ["x"] = 0.554, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15189, ["x"] = 0.554, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[8278] = { ["id"] = 8278, ["name"] = "Noggle's Last Hope", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8278 }, ["description"] = "Blasted! The antidote didn't work. Noggle must've been stung by one of the stronger creatures in the far south. I'm going to need you to go there and get me some more samples, <name>. The good news is that since their poison is stronger I won't require as many. The bad news is that there are more kinds of poisonous creatures crawling around the southern area so you'll have to draw from more sources.", ["objectivesText"] = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 3 Stonelash Pincer Stingers , 3 Stonelash Flayer Stingers and 3 Rock Stalker Fangs . Progress: This is our last chance to save Noggle! Hurry!", ["rewardGold"] = 78750, ["rewardXP"] = 2090, ["rewardItems"] = { 13444, 13446, 20374, 20375, 20377 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15189, ["x"] = 0.554, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15189, ["x"] = 0.554, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[8279] = { ["id"] = 8279, ["name"] = "The Twilight Lexicon", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["series"] = { 8284, 8285, 8287 }, ["description"] = "The Twilight's Hammer are not kind to those that leave their ranks. They hunt me to this day like I'm some sort of beast! Needless to say, an enemy of theirs is a friend of mine! To decipher this Tablet I'll need the book used by their scribes to encode secret messages: the Twilight Lexicon. It's such an important tool that they keep its three chapters in different locations! The officers entrusted with the Lexicon are known as Twilight Keepers. Look for them at the Twilight's Hammer camps.", ["objectivesText"] = "Bring the three chapters of the Twilight Lexicon to Hermit Ortell in Silithus . Progress: Who goes there? Oh, it's you! Did you find all the Lexicon chapters yet?", ["rewardGold"] = 105000, ["rewardXP"] = 2615, ["rewardItems"] = { 20394, 20395, 20396 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15194, ["x"] = 0.685, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15194, ["x"] = 0.685, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 9, ["flags"] = 0 } } },
[8280] = { ["id"] = 8280, ["name"] = "Securing the Supply Lines", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8280 }, ["series"] = { 8281, 28527, 28528, 28856, 28859 }, ["description"] = "Cenarion Hold is a location of utmost strategic importance. I'm convinced that while we hold it our victory over the silithid is guaranteed. Provided our influx supplies can be maintained, that is. Desert worms have proven to be more of a threat to our supply caravans than even the silithid themselves. Just this morning, a large shipment of morrowgrain was ravaged by a group of dredge strikers . I need you to thin their numbers to ensure our supplies aren't jeopardized.", ["objectivesText"] = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers .", ["rewardGold"] = 99850, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15191, ["x"] = 0.548, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15191, ["x"] = 0.548, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[8281] = { ["id"] = 8281, ["name"] = "Stepping Up Security", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8281 }, ["series"] = { 8280, 28527, 28528, 28856, 28859 }, ["description"] = "Your performance has been truly exemplary so far, <name>. Our supply lines are not completely safe yet, however. In the absence of dredge strikers, their larger southern cousins will surely move in to take their place in the north. You'll have to kill quite a few dredge crushers to keep them at bay, but we cannot leave the safety of our supply lines to chance.", ["objectivesText"] = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to slay 20 Dredge Crushers .", ["rewardGold"] = 683200, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15191, ["x"] = 0.548, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15191, ["x"] = 0.548, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[8282] = { ["id"] = 8282, ["name"] = "Noggle's Lost Satchel", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8282 }, ["description"] = "Where am I? Where's my bag? *gasp* I must've lost it while fleeing from Deathclasp, the giant scorpid. In my rush to escape I walked right into a nest of stonelash flayers. The satchel I was carrying had all sorts of rare reagents in it. Without them, me and Beetix won't be able to make the potions that Cenarion Hold needs. I'm too weak to get up yet, but I can make it worth your while if you bring back my reagents. I ran into Deathclasp in the southern mountain range, behind Bronzebeard's camp.", ["objectivesText"] = "Retrieve Noggle's Satchel from the mountains in the south of Silithus and return it to him at Cenarion Hold. Progress: Still haven't found my bag? Well I should count my lucky stars, at least the poison's been cleansed.", ["rewardXP"] = 2090, ["rewardItems"] = { 13447, 13452, 20379 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15190, ["x"] = 0.554, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15190, ["x"] = 0.554, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[8283] = { ["id"] = 8283, ["name"] = "Wanted - Deathclasp, Terror of the Sands", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8283 }, ["description"] = "The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity. She presents a great threat to patrols and expeditions in the southern regions. Individuals participating in her destruction will be remunerated handsomely. Inquire with Captain Vish Kozus , at the top of the Cenarion Hold Watchtower, regarding a reward.", ["objectivesText"] = "Bring Deathclasp's Pincer to Vish Kozus , Captain of the Guard. Progress: I'll need the creature's pincer as proof of the deed. No pincer, no reward.", ["rewardGold"] = 199700, ["rewardXP"] = 2615, ["rewardItems"] = { 20385, 20646, 20647 }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15182, ["x"] = 0.545, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[8284] = { ["id"] = 8284, ["name"] = "The Twilight Mystery", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["series"] = { 8279, 8285, 8287 }, ["description"] = "A camp of Twilight's Hammer cultists once thrived northwest of here. If you were to venture there now, you'd find the area swarming with elementals and nothing but scattered pieces of wood and canvas to mark the spot where the camp was. I've recovered a few fragments of a clay tablet from the site, but I have too few of them to piece together anything useful. See if you can find the remaining tablet fragments so we can shed some light into the Twilight's Hammer presence here in Silithus .", ["objectivesText"] = "Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments . Progress: The ravaged camp can be found northwest of here. Come back when you have all the fragments.", ["rewardGold"] = 99850, ["rewardXP"] = 2090, ["rewardItems"] = { 20378 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15183, ["x"] = 0.535, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15183, ["x"] = 0.535, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 2, ["flags"] = 0 } } },
[8285] = { ["id"] = 8285, ["name"] = "The Deserter", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["series"] = { 8279, 8284, 8287 }, ["description"] = "There are rumors of a Twilight's Hammer member called Ortell having deserted his sect. Word has it he hid in the mountains south of Southwind Village, where he lives as a hermit. Perhaps you can enlist his help in deciphering the tablet. Take the restored tablet with you and seek out Ortell.", ["objectivesText"] = "Take the restored tablet to Hermit Ortell in Silithus . Progress: You! How did you find me? Who are you? You weren't followed, were you? Speak!", ["rewardGold"] = 105000, ["rewardXP"] = 1570, ["rewardItems"] = { 20401, 33249, 57832, 57853, 131657, 131658 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15183, ["x"] = 0.535, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15194, ["x"] = 0.685, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 8, ["flags"] = 0 } } },
[8287] = { ["id"] = 8287, ["name"] = "A Terrible Purpose", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["series"] = { 8279, 8284, 8285 }, ["description"] = "Ok, here we are... a pretty valuable chunk of information, I must say! I've seen the Cenarion Circle forces arrive at Silithus . They plan to drive the Twilight's Hammer out, don't they? This will help. Take this parchment to their leader, Commander Mar'alith . Soon the Twilight's Hammer will be vanquished and I will be outside their grasp for good!", ["objectivesText"] = "Take the Decoded Tablet Parchment to Commander Mar'alith . Progress: What is this you bring to me, <name>?", ["rewardGold"] = 199700, ["rewardXP"] = 2090, ["rewardItems"] = { 20405 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15194, ["x"] = 0.685, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15181, ["x"] = 0.532, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 11, ["flags"] = 0 } } },
[8304] = { ["id"] = 8304, ["name"] = "Dearest Natalia", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["series"] = { 8306 }, ["description"] = "My dear Natalia has gone missing. Truth be told, she had been acting strangely for weeks leading up to her disappearance. I had caught her talking to herself when no one was around on more than one occasion. She was adamant that everything was ok and that she must be allowed to continue her research. She was last seen heading to Bronzebeard's camp to the south. My soldiers are spread too thin, <name>. I need you to go to Bronzebeard's camp and question those dwarves.", ["objectivesText"] = "Question Frankal and Rutgar at Bronzebeard's Encampment about the whereabouts of Natalia Mar'alith.", ["rewardXP"] = 2090, ["rewardItems"] = { 68032 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15181, ["x"] = 0.532, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15181, ["x"] = 0.532, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 3, ["flags"] = 0 } } },
[8306] = { ["id"] = 8306, ["name"] = "Into The Maw of Madness", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["series"] = { 8304 }, ["description"] = "I need you to venture into Hive'Regal and find what became of my dearest Natalia, <name>. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you speak with those dwarves further. They might be able to give you some tips on dealing with the silithid that inhabit that hive. And <name>, if she truly is as mad as they say... do what you must.", ["objectivesText"] = "Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith . Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you. And <name>, remember the Commander's words: \"Do what you must...\" Progress: Natalia?", ["rewardGold"] = 199700, ["rewardXP"] = 2615, ["rewardItems"] = { 20724 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15181, ["x"] = 0.532, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15181, ["x"] = 0.532, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 4, ["flags"] = 0 } } },
[8308] = { ["id"] = 8308, ["name"] = "Brann Bronzebeard's Lost Letter", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8308 }, ["description"] = "To Whom It May Concern: If you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow. Found information about a Titan. Great battle between him and an Old God. Yes, a bona fide Old God. Found ancient tunnel leading to Ahn'Qiraj. Taking it. Take this letter to my old camp. Make sure my monkey is getting adequate food, water, and hugs. -Brann Bronzebeard, Explorer Extreme P.S. Watch out for crazy Old God worshipping night elf.", ["objectivesText"] = "Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus . Progress: Oh dear.", ["rewardXP"] = 2615, ["rewardItems"] = { 20461, 20723 }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15170, ["x"] = 0.464, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["startItems"] = { 20461 } },
[8309] = { ["id"] = 8309, ["name"] = "Glyph Chasing", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["description"] = "After our initial foray into the hives and Mistress Mar'alith's subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals. If I can get rubbings of those crystals and the glyphs on them, we might be able to make sense of this madness. Take this transcription set and hit Hive'Regal to the east, <name>. That's the last rubbing I need!", ["objectivesText"] = "Use the Geologist's Transcription Kit to make a Hive'Regal Rubbing from the Hive'Regal Glyphed Crystal. Progress: If you find some crazy night elf lass in there, be sure to give her a kick in the duff.", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 20453, 20456 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15170, ["x"] = 0.464, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15170, ["x"] = 0.464, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 5, ["flags"] = 0 } } },
[8310] = { ["id"] = 8310, ["name"] = "Breaking the Code", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["description"] = "I think I can formulate an elixir that will allow us to more readily decipher the glyphs and language of the silithid and Qiraji! What do I need? Glad you asked! I need brains! Normally I'd need a brain from each silithid type that inhabit the hives. Another brave explorer brought me two of 'em here... and never came back from Hive'Regal. Bring me back a silithid brain from Hive'Regal... and be careful not to end up like him!", ["objectivesText"] = "Obtain an intact Hive'Regal Silithid Brain from any silithid in Hive'Regal. Progress: Go play with the monkey, kid. I don't have time for this.", ["rewardGold"] = 117300, ["rewardXP"] = 2615, ["rewardItems"] = { 20459, 20461 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15171, ["x"] = 0.46, ["y"] = 0.792 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15171, ["x"] = 0.46, ["y"] = 0.792 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.792 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 6, ["flags"] = 0 } } },
[8314] = { ["id"] = 8314, ["name"] = "Unraveling the Mystery", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["description"] = "We're on the verge of a breakthrough, <name>! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid. Unfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals. Take the glyphed crystal prism to Geologist Larksbane at Cenarion Hold. She might be able to help.", ["objectivesText"] = "Deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus . Progress: Oh my! What do you have there, <name>?", ["rewardXP"] = 1570, ["rewardItems"] = { 20463 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15170, ["x"] = 0.464, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15183, ["x"] = 0.535, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 7, ["flags"] = 0 } } },
[8318] = { ["id"] = 8318, ["name"] = "Secret Communication", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8318 }, ["description"] = "Some of the Twilight's Hammer cultists carry around little papers with gibberish written on them. I want you to bring me a stack of them, <class>. I can't figure out what the gibberish means, but that's not the point! These papers are how their different groups communicate secretly. The more texts we take out of circulation, the less they can communicate!", ["objectivesText"] = "Bring 10 Encrypted Twilight Texts to Bor Wildmane in Cenarion Hold. Progress: Did you bring me some texts?", ["rewardGold"] = 683200, ["rewardXP"] = 2090, ["rewardItems"] = { 20404 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15306, ["x"] = 0.532, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15306, ["x"] = 0.532, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[8319] = { ["id"] = 8319, ["name"] = "Encrypted Twilight Texts", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8319 }, ["objectivesText"] = "Progress: Keep bringing me texts. We'll soon force the Twilight's Hammer out of Silithus .", ["rewardItems"] = { 20404 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15306, ["x"] = 0.532, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15306, ["x"] = 0.532, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[8320] = { ["id"] = 8320, ["name"] = "Twilight Geolords", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["series"] = { 8321 }, ["description"] = "The Twilight's Hammer, an insane cult bent on destruction, set up camps in Silithus and perform rituals day and night. We do not yet know their plans, but we do think they are somehow linked to the pulsing red crystals spread across the desert. Although their mystery may one day be solved, we must first deal with their immediate threat. Go to their camps to the west and seek out Twilight geolords . They are the heads of these serpents; that is where we must strike!", ["objectivesText"] = "Kill 10 Twilight Geolords , then return to Huum Wildmane in Cenarion Hold.", ["rewardGold"] = 99850, ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15270, ["x"] = 0.532, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15270, ["x"] = 0.532, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 0, ["flags"] = 0 } } },
[8321] = { ["id"] = 8321, ["name"] = "Vyral the Vile", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["series"] = { 8320 }, ["description"] = "We have discovered another base of operations for the Twilight's Hammer. It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus . The local leader of the cult, Vyral the Vile, haunts that cave - it is he who you must next defeat. When you have done this, bring me his signet ring. Fortune to you, <name>. The horrors of Twilight's Run are formidable indeed.", ["objectivesText"] = "Slay Vyral the Vile and obtain Vyral's Signet Ring . Progress: <name>, have you yet defeated Vyral the Vile? Do you have his signet ring?", ["rewardGold"] = 683200, ["rewardXP"] = 2615, ["rewardItems"] = { 20466, 20649, 20650 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15270, ["x"] = 0.532, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15270, ["x"] = 0.532, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 1, ["flags"] = 0 } } },
[8323] = { ["id"] = 8323, ["name"] = "True Believers", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8279, 8284, 8285, 8287, 8304, 8306, 8309, 8310, 8314, 8320, 8321, 8323 }, ["description"] = "Now that I have the Twilight Lexicon in my possession, there is a small favor I'd like to ask of you. My former organization has a secret encoded bulletin they circulate on a monthly basis. If they make any progress searching for me or if they call off the search, word will be published on the True Believer. Although this information is obviously valuable to me, the publication contains other useful information that I can share. Bring me any encoded texts you find on Twilight's Hammer members.", ["objectivesText"] = "Hermit Ortell wants you to bring him 10 Encrypted Twilight Texts . Progress: Did you find any encrypted texts? I'm quite curious to read this month's True Believer.", ["rewardGold"] = 99850, ["rewardXP"] = 2090, ["rewardItems"] = { 20404, 20469 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15194, ["x"] = 0.685, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15194, ["x"] = 0.685, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 506, ["name"] = "Silithus", ["orderIndex"] = 10, ["flags"] = 0 } } },
[8324] = { ["id"] = 8324, ["name"] = "Still Believing", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 8324 }, ["objectivesText"] = "Progress: Find any more encrypted texts? Bring me a good batch of them, this decoding work takes some time.", ["rewardGold"] = 52500, ["rewardItems"] = { 20404, 20469 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 15194, ["x"] = 0.685, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 15194, ["x"] = 0.685, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[8470] = { ["id"] = 8470, ["name"] = "Deadwood Ritual Totem", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 8470 }, ["description"] = "You have found one of the Deadwood furbolg's ritual totems. The totem itself is of non-descript construction, but a palpable sense of despair emanates from it. If there were any object that might best exemplify the corruption that the Deadwood furbolg suffer under, this item would clearly be it. One of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.", ["objectivesText"] = "Take the Deadwood Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item. The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them. Progress: Yes <class>, what can I assist you with? You walk among us peacefully, though there is assuredly something amiss. I sense something... something troubling...", ["rewardGold"] = 105000, ["rewardXP"] = 2090, ["rewardItems"] = { 13444, 13446, 20741 }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 11558, ["x"] = 0.6452, ["y"] = 0.0484 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.6452, ["y"] = 0.0484 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "standard", ["startItems"] = { 20741 } },
[8481] = { ["id"] = 8481, ["name"] = "The Root of All Evil", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 0, ["zoneID"] = 361, ["mapID"] = 77, ["storyline"] = { 8481 }, ["description"] = "<name>, thanks to you we have devised a way to summon forth the root of all evil for the Winterfall tribe - the corrupting demon that dominates them! Take this torch to the mouth of Grolnar's personal cave and plant it there. Doing so will force the demon to reveal itself and investigate. This is when you and your allies must strike it down! Only the essence of the fallen demon will begin the lengthy healing process of the Winterfall tribe... and the salvation of Timbermaw Hold .", ["objectivesText"] = "Plant the Demon Summoning Torch in the mouth of Grolnar's cave in the Winterfall furbolg village. Defeat the demon and retrieve the Essence of Xandivious for Gorn One Eye in Timbermaw Hold . Progress: You have returned to us, <name>... does this mean that the demon has been slain?", ["rewardXP"] = 2090, ["rewardItems"] = { 13458, 21144, 21145, 21326 }, ["starts"] = { { ["mapID"] = 77, ["npcID"] = 11555, ["x"] = 0.498, ["y"] = 0.191 } }, ["ends"] = { { ["mapID"] = 77, ["npcID"] = 11555, ["x"] = 0.498, ["y"] = 0.191 } }, ["coords"] = { ["mapID"] = 77, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.191 }, ["mapCandidates"] = { ["npc"] = { 77 }, ["zone"] = { 361 } }, ["questType"] = "group" },
