[9268] = { ["id"] = 9268, ["name"] = "War at Sea", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 9268 }, ["objectivesText"] = "Progress: You seek to befriend the goblins of Tanaris once again, <name>? We're in need of materials for sails and guns to fight off our old enemies, the Bloodsail Buccaneers. Bring me mageweave and strong flux and we'll be on our way to pardoning your trespasses.", ["rewardGold"] = 9985, ["rewardXP"] = 260, ["rewardItems"] = { 3466, 4338 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 16417, ["x"] = 0.504, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 16417, ["x"] = 0.504, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[9415] = { ["id"] = 9415, ["name"] = "Report to Marshal Bluewall", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 9415 }, ["description"] = "Are you Marshal Bluewall 's new recruits? Of course you are. What are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them? Now, get going and don't dry out on the way.", ["objectivesText"] = "Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", ["starts"] = { { ["mapID"] = 81, ["npcID"] = 17082, ["x"] = 0.545, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 17080, ["x"] = 0.395, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[9416] = { ["id"] = 9416, ["name"] = "Report to General Kirika", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 0, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 9416 }, ["description"] = "You must be one of General Kirika 's new recruits. It's about time you showed up. Bodies wear down quick in the desert. The dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus . Get your instructions from the General. It's not my job to train you, just find you.", ["objectivesText"] = "Speak with General Kirika at the Horde encampment near Hive'Regal.", ["starts"] = { { ["mapID"] = 81, ["npcID"] = 17081, ["x"] = 0.53, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 17079, ["x"] = 0.545, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
